<include file="Public:header"/>	<style type="text/css">		.video-js{			height: 100% !important;		}	</style>	<form id="myform" method="post" action="{pigcms{:U('course_audit')}" enctype="multipart/form-data" frame="true" refresh="true">		<input type="hidden" name="course_id" value="{pigcms{$detail.course_id}">		<table cellpadding="0" cellspacing="0" class="frame_form" width="100%">			<tr>				<th width="15%">标题</th>				<td width="85%">{pigcms{$detail.title}</td>			</tr>            <tr>                <th width="15%">详情描写</th>                <td width="85%">{pigcms{$detail.content}</td>            </tr>			<tr>				<th width="15%">查看所需积分</th>				<td width="85%"><input type="text" name="score" value="{pigcms{$detail.score}"></td>			</tr>            <tr>                <th width="15%">虚拟查看数量</th>                <td width="85%"><input type="text" name="fictitious_num" value="{pigcms{$detail.fictitious_num}"></td>            </tr>			<tr>				<th width="15%">查看视频</th>				<td width="85%">			    <div style="width:100%;height:250px;" class="rel">			        <video id="my-video" class="video-js vjs-default-skin w100 h100" controls poster="{pigcms{:file_domain().$detail['cover_img']}" data-setup="{}">                        <source src="{pigcms{:file_domain().$detail['videoUrl']}" type='video/mp4' />			            <source src="{pigcms{$static_path}recruit/images/11.webm" type='video/webm' />			            <source src="{pigcms{$static_path}recruit/images/11.ogv" type='video/ogg' />			        </video>			    </div>				{pigcms{$detail.phone}				</td>			</tr>			<tr >				<th width="15%">封面图片</th>				<td id="product_detail_td">                                   <ul class="image_list" id="product_detail">                    <if condition="$detail.cover_img neq ''">                        <li  class="upload_pic_li" style="float:left;list-style:none;">                        	<a href="javascript:void(0);" onclick="window.o2oTop.artiframe('{pigcms{:U('view_image',array('url'=>urlencode(file_domain().$detail['cover_img'])))}','查看大图',700,600,true,false,false,'','',true);"><img src="{pigcms{:file_domain().$detail['cover_img']}" style="width:90px;height:50px;margin-right:5px;"></a><br>                        </li>                    </if>                    </ul>				</td>							</tr>            <tr >                <th width="15%">图片</th>                <td id="product_detail_td">                                   <ul class="image_list" id="product_detail">                    <if condition="$detail.imgUrl neq ''">                        <volist name="detail.imgUrl" id="vo">                            <li  class="upload_pic_li" style="float:left;list-style:none;">                                <a href="javascript:void(0);" onclick="window.o2oTop.artiframe('{pigcms{:U('view_image',array('url'=>$vo))}','查看大图',700,600,true,false,false,'','',true);"><img src="{pigcms{:file_domain().$vo}" style="width:90px;height:50px;margin-right:5px;"></a><br>                            </li>                        </volist>                    </if>                    </ul>                </td>                            </tr>			<tr>				<th width="15%">状态</th>				<td width="35%">                         <label style="float:left;width:60px" class="checkbox_status"><input type="radio" class="input_radio" name="status" <if condition="1 eq $detail['status']">checked="checked"</if> value="1"/> 通过</label>                        <label style="float:left;width:60px" class="checkbox_status"><input type="radio" class="input_radio" name="status" <if condition="1 neq $detail['status']">checked="checked"</if> value="2" /> 不通过</label>                </td>			</tr>				<tr>				<th width="15%">原因</th>				<td width="35%">                   <input type="text" class="input fl" name="reason" value="{pigcms{$detail.reason}" placeholder="审核原因"/>                </td>			</tr>					</table>		<div class="btn hidden">			<input type="submit" name="dosubmit" id="dosubmit" value="提交" class="button" />			<input type="reset" value="取消" class="button" />		</div>	</form><link rel="stylesheet" type="text/css" href="{pigcms{$static_path}css/video-js.min.css"><script src="{pigcms{$static_path}js/video.min.js"></script><script  type="text/javascript">    var View={        init:function(){            this.video();            this.initClick()        },        setting:{            myPlayer:null,            can_view : '{pigcms{$can_view|intval}'        },        video:function(){            var self=this;            videojs("my-video").ready(function(){                self.setting.myPlayer = this;                play_ready()                // self.setting.myPlayer.play();            });            var play_ready=function(){                //播放开始                self.setting.myPlayer.on("play",function(){                    $(".video_content_modal").hide();                });                //播放结束                self.setting.myPlayer.on("ended",function(){                })                //暂停                self.setting.myPlayer.on("pause",function(){                })                //加载时                self.setting.myPlayer.on("loadstart",function(){                })                //离开全屏时                self.setting.myPlayer.on("enterFullScreen",function(){                })            }        },        initClick:function(){            var self=this;            $(document).on("click",".vjs-big-play-button",function(){                self.setting.myPlayer.play();            })        }    }    window.View=View;    View.init();</script><include file="Public:footer"/>